/* DAWAH X — ahmad, অধ্যায় 23 · খণ্ড 23 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][23]=[[4401,4401,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْخَالِقِ ‏ ‏قَالَ سَأَلْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏النَّبِيذِ ‏ ‏فَقَالَ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ عِنْدَ مِنْبَرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا قَدِمَ ‏ ‏وَفْدُ عَبْدِ الْقَيْسِ ‏ ‏مَعَ ‏ ‏الْأَشَجِّ ‏ ‏فَسَأَلُوا نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الشَّرَابِ فَقَالَ ‏ ‏لَا تَشْرَبُوا فِي ‏ ‏حَنْتَمَةٍ ‏ ‏وَلَا فِي ‏ ‏دُبَّاءٍ ‏ ‏وَلَا ‏ ‏نَقِيرٍ ‏ ‏فَقُلْتُ لَهُ يَا ‏ ‏أَبَا مُحَمَّدٍ ‏ ‏وَالْمُزَفَّتُ ‏ ‏فَظَنَنْتُ أَنَّهُ نَسِيَ فَقَالَ لَمْ أَسْمَعْهُ يَوْمَئِذٍ مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏وَقَدْ كَانَ يَكْرَهُهُ ‏","","",""],[4402,4402,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْحَكَمِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ثَمَنِ ‏ ‏عَسْبِ ‏ ‏الْفَحْلِ ‏","","",""],[4403,4403,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏غَيْلَانَ بْنَ سَلَمَةَ الثَّقَفِيَّ ‏ ‏أَسْلَمَ وَتَحْتَهُ عَشْرُ نِسْوَةٍ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اخْتَرْ مِنْهُنَّ أَرْبَعًا ‏ ‏فَلَمَّا كَانَ فِي عَهْدِ ‏ ‏عُمَرَ ‏ ‏طَلَّقَ نِسَاءَهُ وَقَسَمَ مَالَهُ بَيْنَ بَنِيهِ فَبَلَغَ ذَلِكَ ‏ ‏عُمَرَ ‏ ‏فَقَالَ إِنِّي لَأَظُنُّ الشَّيْطَانَ فِيمَا يَسْتَرِقُ مِنْ السَّمْعِ سَمِعَ بِمَوْتِكَ فَقَذَفَهُ فِي نَفْسِكَ وَلَعَلَّكَ أَنْ لَا تَمْكُثَ إِلَّا قَلِيلًا وَايْمُ اللَّهِ لَتُرَاجِعَنَّ نِسَاءَكَ وَلَتَرْجِعَنَّ فِي مَالِكَ أَوْ لَأُوَرِّثُهُنَّ مِنْكَ وَلَآمُرَنَّ بِقَبْرِكَ فَيُرْجَمُ كَمَا رُجِمَ قَبْرُ ‏ ‏أَبِي رِغَالٍ ‏","","",""],[4404,4404,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ الْعَوَّامِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَتَبَ كِتَابَ ‏ ‏الصَّدَقَةِ ‏ ‏فَلَمْ يُخْرِجْهُ إِلَى عُمَّالِهِ حَتَّى ‏ ‏قُبِضَ ‏ ‏فَقَرَنَهُ بِسَيْفِهِ فَلَمَّا ‏ ‏قُبِضَ ‏ ‏عَمِلَ بِهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَتَّى ‏ ‏قُبِضَ ‏ ‏ثُمَّ ‏ ‏عُمَرُ ‏ ‏حَتَّى ‏ ‏قُبِضَ ‏ ‏فَكَانَ فِيهِ ‏ ‏فِي خَمْسٍ مِنْ الْإِبِلِ شَاةٌ وَفِي عَشْرٍ شَاتَانِ وَفِي خَمْسَ عَشْرَةَ ثَلَاثُ شِيَاهٍ وَفِي عِشْرِينَ أَرْبَعُ شِيَاهٍ وَفِي خَمْسٍ وَعِشْرِينَ ‏ ‏ابْنَةُ مَخَاضٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏ثُمَّ أَصَابَتْنِي ‏ ‏عِلَّةٌ ‏ ‏فِي مَجْلِسِ ‏ ‏عَبَّادِ بْنِ الْعَوَّامِ ‏ ‏فَكَتَبْتُ تَمَامَ الْحَدِيثِ فَأَحْسَبُنِي لَمْ أَفْهَمْ بَعْضَهُ فَشَكَكْتُ فِي بَقِيَّةِ الْحَدِيثِ فَتَرَكْتُهُ ‏ ‏بِهَذَا الْحَدِيثِ فِي الْمُسْنَدِ ‏ ‏فِي حَدِيثِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏لِأَنَّهُ كَانَ قَدْ جَمَعَ حَدِيثَ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏فَحَدَّثَنَا بِهِ فِي حَدِيثِ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَزِيدَ ‏ ‏بِتَمَامِهِ ‏ ‏وَفِي حَدِيثِ ‏ ‏عَبَّادٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ الْعَوَّامِ ‏","","",""],[4405,4405,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ يَعْنِي الْوَاسِطِيَّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ يَعْنِي ابْنَ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ كَتَبَ ‏ ‏الصَّدَقَةَ ‏ ‏وَلَمْ يُخْرِجْهَا إِلَى عُمَّالِهِ حَتَّى تُوُفِّيَ قَالَ فَأَخْرَجَهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏مِنْ بَعْدِهِ فَعَمِلَ بِهَا حَتَّى تُوُفِّيَ ثُمَّ أَخْرَجَهَا ‏ ‏عُمَرُ ‏ ‏مِنْ بَعْدِهِ فَعَمِلَ بِهَا قَالَ فَلَقَدْ هَلَكَ ‏ ‏عُمَرُ ‏ ‏يَوْمَ هَلَكَ وَإِنَّ ذَلِكَ لَمَقْرُونٌ بِوَصِيَّتِهِ فَقَالَ كَانَ فِيهَا ‏ ‏فِي الْإِبِلِ فِي كُلِّ خَمْسٍ شَاةٌ حَتَّى تَنْتَهِيَ إِلَى أَرْبَعٍ وَعِشْرِينَ فَإِذَا بَلَغَتْ إِلَى خَمْسٍ وَعِشْرِينَ فَفِيهَا ‏ ‏بِنْتُ مَخَاضٍ ‏ ‏إِلَى خَمْسٍ وَثَلَاثِينَ فَإِنْ لَمْ تَكُنْ ‏ ‏ابْنَةُ مَخَاضٍ ‏ ‏فَابْنُ لَبُونٍ ‏ ‏فَإِذَا زَادَتْ عَلَى خَمْسٍ وَثَلَاثِينَ فَفِيهَا ‏ ‏ابْنَةُ لَبُونٍ ‏ ‏إِلَى خَمْسٍ وَأَرْبَعِينَ فَإِذَا زَادَتْ وَاحِدَةٌ فَفِيهَا ‏ ‏حِقَّةٌ ‏ ‏إِلَى سِتِّينَ فَإِذَا زَادَتْ فَفِيهَا ‏ ‏جَذَعَةٌ ‏ ‏إِلَى خَمْسٍ وَسَبْعِينَ فَإِذَا زَادَتْ فَفِيهَا ‏ ‏ابْنَتَا لَبُونٍ ‏ ‏إِلَى تِسْعِينَ فَإِذَا زَادَتْ فَفِيهَا ‏ ‏حِقَّتَانِ ‏ ‏إِلَى عِشْرِينَ وَمِائَةٍ فَإِذَا كَثُرَتْ الْإِبِلُ فَفِي كُلِّ خَمْسِينَ ‏ ‏حِقَّةٌ ‏ ‏وَفِي كُلِّ أَرْبَعِينَ ‏ ‏ابْنَةُ لَبُونٍ ‏ ‏وَفِي الْغَنَمِ مِنْ أَرْبَعِينَ شَاةٌ إِلَى عِشْرِينَ وَمِائَةٍ فَإِذَا زَادَتْ فَفِيهَا شَاتَانِ إِلَى مِائَتَيْنِ فَإِذَا زَادَتْ فَفِيهَا ثَلَاثٌ إِلَى ثَلَاثِ مِائَةٍ فَإِذَا زَادَتْ بَعْدُ فَلَيْسَ فِيهَا شَيْءٌ حَتَّى تَبْلُغَ أَرْبَعَ مِائَةٍ فَإِذَا كَثُرَتْ الْغَنَمُ فَفِي كُلِّ مِائَةٍ شَاةٌ وَكَذَلِكَ لَا يُفَرَّقُ بَيْنَ مُجْتَمِعٍ وَلَا يُجْمَعُ بَيْنَ مُتَفَرِّقٍ مَخَافَةَ ‏ ‏الصَّدَقَةِ ‏ ‏وَمَا كَانَ مِنْ ‏ ‏خَلِيطَيْنِ ‏ ‏فَهُمَا يَتَرَاجَعَانِ بِالسَّوِيَّةِ لَا تُؤْخَذُ ‏ ‏هَرِمَةٌ ‏ ‏وَلَا ذَاتُ عَيْبٍ مِنْ الْغَنَمِ ‏","","",""],[4406,4406,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَعْتَقَ نَصِيبًا ‏ ‏أَوْ قَالَ ‏ ‏شَقِيصًا ‏ ‏لَهُ أَوْ قَالَ شِرْكًا ‏ ‏لَهُ فِي عَبْدٍ فَكَانَ لَهُ مِنْ الْمَالِ مَا بَلَغَ ثَمَنَهُ بِقِيمَةِ ‏ ‏الْعَدْلِ ‏ ‏فَهُوَ عَتِيقٌ وَإِلَّا فَقَدْ عَتَقَ مِنْهُ ‏ ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏كَانَ ‏ ‏نَافِعٌ ‏ ‏رُبَّمَا قَالَ فِي هَذَا الْحَدِيثِ وَرُبَّمَا لَمْ يَقُلْهُ فَلَا أَدْرِي أَهُوَ فِي الْحَدِيثِ أَوْ قَالَهُ ‏ ‏نَافِعٌ ‏ ‏مِنْ ‏ ‏قِبَلِهِ ‏ ‏يَعْنِي قَوْلَهُ فَقَدْ عَتَقَ مِنْهُ مَا عَتَقَ ‏","","",""],[4407,4407,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏قَفَلَ ‏ ‏مِنْ غَزْوٍ أَوْ حَجٍّ أَوْ عُمْرَةٍ فَعَلَا ‏ ‏فَدْفَدًا ‏ ‏مِنْ الْأَرْضِ أَوْ ‏ ‏شَرَفًا ‏ ‏قَالَ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏ ‏آيِبُونَ ‏ ‏تَائِبُونَ سَاجِدُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ صَدَقَ اللَّهُ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ ‏","","",""],[4408,4408,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَسْتَرْعِي ‏ ‏اللَّهُ تَبَارَكَ وَتَعَالَى عَبْدًا رَعِيَّةً قَلَّتْ أَوْ كَثُرَتْ إِلَّا سَأَلَهُ اللَّهُ تَبَارَكَ وَتَعَالَى عَنْهَا يَوْمَ الْقِيَامَةِ أَقَامَ فِيهِمْ أَمْرَ اللَّهِ تَبَارَكَ وَتَعَالَى أَمْ أَضَاعَهُ حَتَّى يَسْأَلَهُ عَنْ أَهْلِ بَيْتِهِ خَاصَّةً ‏","","",""],[4409,4409,"","","‏ ‏حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُسْلِمٍ ‏ ‏أَخِي ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَزَالُ الْمَسْأَلَةُ بِأَحَدِكُمْ حَتَّى يَلْقَى اللَّهَ تَبَارَكَ وَتَعَالَى وَلَيْسَ فِي وَجْهِهِ ‏ ‏مُزْعَةُ ‏ ‏لَحْمٍ ‏","","",""],[4410,4410,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانُوا يَتَبَايَعُونَ الطَّعَامَ ‏ ‏جُزَافًا ‏ ‏عَلَى السُّوقِ ‏ ‏فَنَهَاهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَبِيعُوهُ حَتَّى يَنْقُلُوهُ ‏","","",""],[4411,4411,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ أَهْلُ الْجَاهِلِيَّةِ يَبِيعُونَ لَحْمَ ‏ ‏الْجَزُورِ ‏ ‏بِحَبَلِ حَبَلَةٍ ‏ ‏وَحَبَلُ حَبَلَةٍ ‏ ‏تُنْتَجُ ‏ ‏النَّاقَةُ مَا فِي بَطْنِهَا ثُمَّ تَحْمِلُ الَّتِي تُنْتَجُهُ ‏ ‏فَنَهَاهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ ‏","","",""],[4412,4412,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ قَالَ ‏ ‏عَمْرٌو يَعْنِي ابْنَ دِينَارٍ ‏ ‏ذَكَرُوا الرَّجُلَ ‏ ‏يُهِلُّ ‏ ‏بِعُمْرَةٍ فَيَحِلُّ هَلْ لَهُ أَنْ ‏ ‏يَأْتِيَ ‏ ‏يَعْنِي امْرَأَتَهُ ‏ ‏قَبْلَ أَنْ يَطُوفَ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَسَأَلْنَا ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏فَقَالَ ‏ ‏لَا حَتَّى يَطُوفَ ‏ ‏بِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَسَأَلْنَا ‏ ‏ابْنَ عُمَرَ ‏ ‏فَقَالَ قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَطَافَ ‏ ‏بِالْبَيْتِ ‏ ‏سَبْعًا فَصَلَّى خَلْفَ ‏ ‏الْمَقَامِ ‏ ‏رَكْعَتَيْنِ وَسَعَى بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ قَالَ ‏ { ‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏}","","",""],[4413,4413,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏بَيْنَمَا النَّاسُ يُصَلُّونَ فِي ‏ ‏مَسْجِدِ قُبَاءَ ‏ ‏الْغَدَاةَ ‏ ‏إِذْ جَاءَ ‏ ‏جَاءٍ ‏ ‏فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ أُنْزِلَ عَلَيْهِ اللَّيْلَةَ قُرْآنٌ ‏ ‏وَأُمِرَ أَنْ تُسْتَقْبَلَ ‏ ‏الْكَعْبَةُ ‏ ‏فَاسْتَقْبَلُوهَا وَاسْتَدَارُوا فَتَوَجَّهُوا نَحْوَ ‏ ‏الْكَعْبَةِ ‏","","",""],[4414,4414,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَأْكُلْ أَحَدُكُمْ مِنْ أُضْحِيَّتِهِ فَوْقَ ثَلَاثَةِ أَيَّامٍ ‏ ‏وَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِذَا غَابَتْ الشَّمْسُ مِنْ الْيَوْمِ الثَّالِثِ لَا يَأْكُلُ مِنْ لَحْمِ ‏ ‏هَدْيِهِ ‏","","",""],[4415,4415,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ مُسْكِرٍ حَرَامٌ ‏","","",""],[4416,4416,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ مُسْكِرٍ خَمْرٌ وَكُلُّ مُسْكِرٍ حَرَامٌ ‏","","",""],[4417,4417,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏أَفْضَلُ مِنْ أَلْفَيْ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏","","",""],[4418,4418,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْمُزَابَنَةِ وَالْمُزَابَنَةُ الثَّمَرُ بِالتَّمْرِ كَيْلًا وَالْعِنَبُ بِالزَّبِيبِ كَيْلًا ‏ ‏وَالْحِنْطَةُ ‏ ‏بِالزَّرْعِ كَيْلًا ‏","","",""],[4419,4419,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْغَادِرُ ‏ ‏يُرْفَعُ لَهُ ‏ ‏لِوَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ يُقَالُ هَذِهِ ‏ ‏غَدْرَةُ ‏ ‏فُلَانِ بْنِ فُلَانٍ ‏","","",""],[4420,4420,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَمَلَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا ‏","","",""],[4421,4421,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ أَبُو عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَبِعَ جَنَازَةً حَتَّى يُصَلِّيَ عَلَيْهَا فَإِنَّ لَهُ قِيرَاطًا فَسُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْقِيرَاطِ فَقَالَ مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[4422,4422,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏جَاءَ ‏ ‏رَجُلَانِ ‏ ‏مِنْ أَهْلِ الْمَشْرِقِ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَطَبَا فَعَجِبَ النَّاسُ مِنْ بَيَانِهِمَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ ‏ ‏الْبَيَانِ ‏ ‏سِحْرًا أَوْ إِنَّ بَعْضَ ‏ ‏الْبَيَانِ ‏ ‏سِحْرٌ ‏","","",""],[4423,4423,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًي ‏ ‏رَكْعَتَيْنِ وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَمَعَ ‏ ‏عُمَرَ ‏ ‏وَمَعَ ‏ ‏عُثْمَانَ ‏ ‏صَدْرًا ‏ ‏مِنْ ‏ ‏إِمَارَتِهِ ‏ ‏ثُمَّ أَتَمَّ ‏","","",""],[4424,4424,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْعَلُوا مِنْ صَلَاتِكُمْ فِي بُيُوتِكُمْ وَلَا تَتَّخِذُوهَا قُبُورًا ‏","","",""],[4425,4425,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَنْبَأَنَا ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْفُوا ‏ ‏الشَّوَارِبَ وَأَعْفُوا اللِّحَى ‏","","",""],[4426,4426,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمْنَعُوا ‏ ‏إِمَاءَ ‏ ‏اللَّهِ مَسَاجِدَ اللَّهِ ‏","","",""],[4427,4427,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَاتَ ‏ ‏بِذِي طُوًى ‏ ‏حَتَّى أَصْبَحَ ثُمَّ دَخَلَ ‏ ‏مَكَّةَ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَفْعَلُ ذَلِكَ ‏","","",""],[4428,4428,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْحَمُ اللَّهُ الْمُحَلِّقِينَ قَالُوا يَا رَسُولَ اللَّهِ وَالْمُقَصِّرِينَ قَالَ يَرْحَمُ اللَّهُ الْمُحَلِّقِينَ قَالَ فِي الرَّابِعَةِ وَالْمُقَصِّرِينَ ‏","","",""],[4429,4429,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْكُمْ أَحَدٌ إِلَّا يُعْرَضُ عَلَيْهِ مَقْعَدُهُ ‏ ‏بِالْغَدَاةِ ‏ ‏وَالْعَشِيِّ إِنْ كَانَ مِنْ أَهْلِ الْجَنَّةِ فَمِنْ أَهْلِ الْجَنَّةِ وَإِنْ كَانَ مِنْ أَهْلِ النَّارِ فَمِنْ أَهْلِ النَّارِ يُقَالُ هَذَا مَقْعَدُكَ حَتَّى تُبْعَثَ إِلَيْهِ ‏","","",""],[4430,4430,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُقِيمُ الرَّجُلُ الرَّجُلَ مِنْ مَجْلِسِهِ فَيَجْلِسَ فِيهِ وَلَكِنْ تَفَسَّحُوا وَتَوَسَّعُوا ‏","","",""],[4431,4431,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ الظُّهْرِ سَجْدَتَيْنِ وَبَعْدَهَا سَجْدَتَيْنِ وَبَعْدَ الْمَغْرِبِ سَجْدَتَيْنِ وَبَعْدَ الْعِشَاءِ سَجْدَتَيْنِ وَبَعْدَ الْجُمُعَةِ سَجْدَتَيْنِ فَأَمَّا الْجُمُعَةُ وَالْمَغْرِبُ فِي بَيْتِهِ قَالَ وَأَخْبَرَتْنِي أُخْتِي ‏ ‏حَفْصَةُ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي سَجْدَتَيْنِ خَفِيفَتَيْنِ إِذَا طَلَعَ الْفَجْرُ قَالَ وَكَانَتْ سَاعَةً لَا أَدْخُلُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا ‏","","",""],[4432,4432,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَرَضَهُ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏وَهُوَ ابْنُ أَرْبَعَ عَشْرَةَ فَلَمْ ‏ ‏يُجِزْهُ ‏ ‏ثُمَّ عَرَضَهُ يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏وَهُوَ ابْنُ خَمْسَ عَشْرَةَ ‏ ‏فَأَجَازَهُ ‏","","",""],[4433,4433,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيَنَامُ أَحَدُنَا وَهُوَ ‏ ‏جُنُبٌ ‏ ‏قَالَ نَعَمْ إِذَا تَوَضَّأَ ‏","","",""],[4434,4434,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَلَ أَهْلَ ‏ ‏خَيْبَرَ ‏ ‏بِشَطْرِ ‏ ‏مَا يَخْرُجُ مِنْ ثَمَرٍ أَوْ زَرْعٍ ‏","","",""],[4435,4435,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَتَسَارَّ ‏ ‏اثْنَانِ دُونَ الثَّالِثِ ‏","","",""],[4436,4436,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ صَاحِبِ الْقُرْآنِ مَثَلُ صَاحِبِ الْإِبِلِ ‏ ‏الْمُعَقَّلَةِ ‏ ‏إِنْ ‏ ‏عَقَلَهَا ‏ ‏صَاحِبُهَا حَبَسَهَا وَإِنْ أَطْلَقَهَا ذَهَبَتْ ‏","","",""],[4437,4437,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ يَهُودِيَّيْنِ زَنَيَا فَأُتِيَ ‏ ‏بِهِمَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَ ‏ ‏بِرَجْمِهِمَا ‏ ‏قَالَ فَرَأَيْتُ الرَّجُلَ يَقِيهَا بِنَفْسِهِ ‏","","",""],[4438,4438,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَدْرَكَ ‏ ‏عُمَرَ ‏ ‏وَهُوَ فِي رَكْبٍ وَهُوَ يَحْلِفُ بِأَبِيهِ فَقَالَ ‏ ‏لَا تَحْلِفُوا بِآبَائِكُمْ لِيَحْلِفْ حَالِفٌ بِاللَّهِ أَوْ لِيَسْكُتْ ‏","","",""],[4439,4439,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏السَّمْعُ وَالطَّاعَةُ عَلَى الْمَرْءِ فِيمَا أَحَبَّ أَوْ كَرِهَ إِلَّا أَنْ يُؤْمَرَ بِمَعْصِيَةٍ فَإِنْ أُمِرَ بِمَعْصِيَةٍ فَلَا سَمْعَ وَلَا طَاعَةَ ‏","","",""],[4440,4440,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ عَلَيْنَا السُّورَةَ فَيَقْرَأُ السَّجْدَةَ فَيَسْجُدُ وَنَسْجُدُ مَعَهُ حَتَّى مَا يَجِدُ أَحَدُنَا مَكَانًا لِمَوْضِعِ جَبْهَتِهِ ‏","","",""],[4441,4441,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصَّلَاةُ فِي الْجَمِيعِ تَزِيدُ عَلَى صَلَاةِ الرَّجُلِ وَحْدَهُ سَبْعًا وَعِشْرِينَ ‏","","",""],[4442,4442,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ نَاسًا مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَوْا لَيْلَةَ الْقَدْرِ فِي الْمَنَامِ فِي السَّبْعِ الْأَوَاخِرِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَاكُمْ قَدْ تَتَابَعْتُمْ فِي السَّبْعِ الْأَوَاخِرِ فَالْتَمِسُوهَا فِي السَّبْعِ الْأَوَاخِرِ ‏","","",""],[4443,4443,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏جُرَيْجٍ ‏ ‏أَوْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَرْبَعُ ‏ ‏خِلَالٍ ‏ ‏رَأَيْتُكَ تَصْنَعُهُنَّ لَمْ أَرَ أَحَدًا يَصْنَعُهُنَّ قَالَ مَا هِيَ قَالَ رَأَيْتُكَ تَلْبَسُ هَذِهِ النِّعَالَ ‏ ‏السِّبْتِيَّةَ ‏ ‏وَرَأَيْتُكَ تَسْتَلِمُ هَذَيْنِ الرُّكْنَيْنِ الْيَمَانِيَيْنِ لَا تَسْتَلِمُ غَيْرَهُمَا وَرَأَيْتُكَ لَا ‏ ‏تُهِلُّ ‏ ‏حَتَّى تَضَعَ رِجْلَكَ فِي ‏ ‏الْغَرْزِ ‏ ‏وَرَأَيْتُكَ ‏ ‏تُصَفِّرُ ‏ ‏لِحْيَتَكَ قَالَ ‏ ‏أَمَّا لُبْسِي هَذِهِ النِّعَالَ ‏ ‏السِّبْتِيَّةَ ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَلْبَسُهَا يَتَوَضَّأُ فِيهَا وَيَسْتَحِبُّهَا وَأَمَّا ‏ ‏اسْتِلَامُ ‏ ‏هَذَيْنِ الرُّكْنَيْنِ فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَلِمُهُمَا ‏ ‏لَا ‏ ‏يَسْتَلِمُ ‏ ‏غَيْرَهُمَا وَأَمَّا تَصْفِيرِي لِحْيَتِي فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَفِّرُ ‏ ‏لِحْيَتَهُ وَأَمَّا إِهْلَالِي إِذَا ‏ ‏اسْتَوَتْ ‏ ‏بِي ‏ ‏رَاحِلَتِي ‏ ‏فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا وَضَعَ رِجْلَهُ فِي ‏ ‏الْغَرْزِ ‏ ‏وَاسْتَوَتْ ‏ ‏بِهِ ‏ ‏رَاحِلَتُهُ ‏ ‏أَهَلَّ ‏","","",""],[4444,4444,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏وَمُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَبْدُ إِذَا أَحْسَنَ عِبَادَةَ رَبِّهِ تَبَارَكَ وَتَعَالَى وَنَصَحَ لِسَيِّدِهِ كَانَ لَهُ الْأَجْرُ مَرَّتَيْنِ ‏","","",""],[4445,4445,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا افْتَتَحَ الصَّلَاةَ رَفَعَ يَدَيْهِ ‏ ‏حَذْوَ ‏ ‏مَنْكِبَيْهِ ‏ ‏وَإِذَا رَكَعَ صَنَعَ مِثْلَ ذَلِكَ وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ صَنَعَ مِثْلَ ذَلِكَ وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ قَالَ رَبَّنَا وَلَكَ الْحَمْدُ وَلَا يَصْنَعُ مِثْلَ ذَلِكَ فِي السُّجُودِ ‏","","",""],[4446,4446,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏حَدَّثَنِي ‏ ‏عُثْمَانُ بْنُ سُرَاقَةَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يُصَلِّي فِي السَّفَرِ قَبْلَهَا وَلَا بَعْدَهَا ‏","","",""],[4447,4447,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏صَلَّى الْمَغْرِبَ وَالْعِشَاءَ ‏ ‏بِجَمْعٍ ‏ ‏بِإِقَامَةٍ وَاحِدَةٍ فَقَالَ لَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ مَالِكٍ ‏ ‏يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏مَا هَذِهِ الصَّلَاةُ فَقَالَ صَلَّيْتُهَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْمَكَانِ بِإِقَامَةٍ وَاحِدَةٍ ‏","","",""],[4448,4448,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏اتَّخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا مِنْ ذَهَبٍ وَكَانَ يَجْعَلُ فَصَّهُ مِمَّا يَلِي كَفَّهُ فَاتَّخَذَهُ النَّاسُ فَرَمَى بِهِ وَاتَّخَذَ خَاتَمًا مِنْ ‏ ‏وَرِقٍ ‏","","",""],[4449,4449,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الرُّؤْيَا جُزْءٌ مِنْ سَبْعِينَ جُزْءًا مِنْ النُّبُوَّةِ ‏","","",""],[4450,4450,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ قَائِمًا عِنْدَ بَابِ ‏ ‏عَائِشَةَ ‏ ‏فَأَشَارَ بِيَدِهِ نَحْوَ الْمَشْرِقِ فَقَالَ ‏ ‏الْفِتْنَةُ ‏ ‏هَاهُنَا حَيْثُ يَطْلُعُ ‏ ‏قَرْنُ الشَّيْطَانِ ‏","","",""],[4451,4451,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَمَّا مَاتَ ‏ ‏عَبْدُ اللَّهِ بْنُ أُبَيٍّ ‏ ‏جَاءَ ابْنُهُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَعْطِنِي قَمِيصَكَ حَتَّى أُكَفِّنَهُ فِيهِ وَصَلِّ عَلَيْهِ وَاسْتَغْفِرْ لَهُ فَأَعْطَاهُ قَمِيصَهُ وَقَالَ آذِنِّي بِهِ فَلَمَّا ذَهَبَ لِيُصَلِّيَ عَلَيْهِ قَالَ ‏ ‏يَعْنِي ‏ ‏عُمَرَ ‏ ‏قَدْ نَهَاكَ اللَّهُ أَنْ تُصَلِّيَ عَلَى الْمُنَافِقِينَ فَقَالَ ‏ ‏أَنَا بَيْنَ خِيرَتَيْنِ ‏ { ‏اسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ ‏} ‏فَصَلَّى عَلَيْهِ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏وَلَا تُصَلِّ عَلَى أَحَدٍ مِنْهُمْ مَاتَ أَبَدًا ‏} ‏قَالَ فَتُرِكَتْ الصَّلَاةُ عَلَيْهِمْ ‏","","",""],[4452,4452,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكَزَ ‏ ‏الْحَرْبَةَ ‏ ‏يُصَلِّي إِلَيْهَا ‏","","",""],[4453,4453,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيَّرَ اسْمَ ‏ ‏عَاصِيَةَ ‏ ‏قَالَ أَنْتِ ‏ ‏جَمِيلَةُ ‏","","",""],[4454,4454,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏زَيْدٌ الْعَمِّىُّ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأُمَّهَاتِ الْمُؤْمِنِينَ فِي ‏ ‏الذَّيْلِ ‏ ‏شِبْرًا فَاسْتَزَدْنَهُ فَزَادَهُنَّ شِبْرًا آخَرَ فَجَعَلْنَهُ ذِرَاعًا فَكُنَّ يُرْسِلْنَ إِلَيْنَا نَذْرَعُ لَهُنَّ ذِرَاعًا ‏","","",""],[4455,4455,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي رَوَّادٍ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ فَحَكَّهَا وَخَلَّقَ مَكَانَهَا ‏","","",""],[4456,4456,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كُنْتُمْ ثَلَاثَةً فَلَا ‏ ‏يَنْتَجِي ‏ ‏اثْنَانِ دُونَ صَاحِبِهِمَا قَالَ قُلْنَا فَإِنْ كَانُوا أَرْبَعًا قَالَ فَلَا يَضُرُّ ‏","","",""],[4457,4457,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي رَوَّادٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏لَا يَدَعُ أَنْ ‏ ‏يَسْتَلِمَ ‏ ‏الْحَجَرَ وَالرُّكْنَ الْيَمَانِي فِي كُلِّ طَوَافٍ ‏","","",""],[4458,4458,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَحَدُكُمْ قَالَ لِأَخِيهِ يَا كَافِرُ فَقَدْ ‏ ‏بَاءَ ‏ ‏بِهَا أَحَدُهُمَا ‏","","",""],[4459,4459,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي لَبِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَغْلِبَنَّكُمْ ‏ ‏الْأَعْرَابُ ‏ ‏عَلَى اسْمِ صَلَاتِكُمْ فَإِنَّهَا الْعِشَاءُ إِنَّمَا يَدْعُونَهَا الْعَتَمَةَ لِإِعْتَامِهِمْ بِالْإِبِلِ لِحِلَابِهَا ‏","","",""],[4460,4460,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُسَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ ‏ ‏مَوْلَى ‏ ‏مَيْمُونَةَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ عَلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏وَهُوَ بِالْبَلَاطِ وَالْقَوْمُ يُصَلُّونَ فِي الْمَسْجِدِ قُلْتُ مَا يَمْنَعُكَ أَنْ تُصَلِّيَ مَعَ النَّاسِ أَوْ الْقَوْمِ قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُصَلُّوا صَلَاةً فِي يَوْمٍ مَرَّتَيْنِ ‏","","",""],[4461,4461,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا وَلَمْ يَتُبْ مِنْهَا حُرِمَهَا فِي الْآخِرَةِ لَمْ يُسْقَهَا ‏","","",""],[4462,4462,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏قَالَ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏الْعَبَّاسَ ‏ ‏اسْتَأْذَنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَنْ يَبِيتَ ‏ ‏بِمَكَّةَ ‏ ‏أَيَّامَ ‏ ‏مِنًي ‏ ‏مِنْ أَجْلِ ‏ ‏السِّقَايَةِ ‏ ‏فَرَخَّصَ لَهُ ‏","","",""],[4463,4463,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الشِّغَارِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِنَافِعٍ ‏ ‏مَا الشِّغَارُ قَالَ يُزَوِّجُ الرَّجُلَ ابْنَتَهُ وَيَتَزَوَّجُ ابْنَتَهُ وَيُزَوِّجُ الرَّجُلَ أُخْتَهُ وَيَتَزَوَّجُ أُخْتَهُ بِغَيْرِ ‏ ‏صَدَاقٍ ‏","","",""],[4464,4464,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ أَبِي سُلَيْمَانَ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏سُئِلْتُ عَنْ الْمُتَلَاعِنَيْنِ أَيُفَرَّقُ بَيْنَهُمَا فِي إِمَارَةِ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏فَمَا دَرَيْتُ مَا أَقُولُ فَقُمْتُ مِنْ مَكَانِي إِلَى مَنْزِلِ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقُلْتُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏الْمُتَلَاعِنَيْنِ ‏ ‏أَيُفَرَّقُ بَيْنَهُمَا فَقَالَ سُبْحَانَ اللَّهِ إِنَّ أَوَّلَ مَنْ سَأَلَ عَنْ ذَلِكَ فُلَانُ بْنُ فُلَانٍ قَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ الرَّجُلَ يَرَى امْرَأَتَهُ عَلَى ‏ ‏فَاحِشَةٍ ‏ ‏فَإِنْ تَكَلَّمَ تَكَلَّمَ بِأَمْرٍ ‏ ‏عَظِيمٍ ‏ ‏وَإِنْ سَكَتَ سَكَتَ عَلَى مِثْلِ ذَلِكَ فَسَكَتَ فَلَمْ يُجِبْهُ فَلَمَّا كَانَ بَعْدُ أَتَاهُ فَقَالَ الَّذِي سَأَلْتُكَ عَنْهُ قَدْ ‏ ‏ابْتُلِيتُ ‏ ‏بِهِ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ هَؤُلَاءِ الْآيَاتِ فِي سُورَةِ ‏ ‏النُّورِ ‏ { ‏وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ ‏ ‏حَتَّى بَلَغَ ‏ ‏أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنْ الصَّادِقِينَ ‏} ‏فَبَدَأَ بِالرَّجُلِ فَوَعَظَهُ وَذَكَّرَهُ وَأَخْبَرَهُ أَنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَةِ فَقَالَ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا كَذَبْتُكَ ثُمَّ ثَنَّى بِالْمَرْأَةِ فَوَعَظَهَا وَذَكَّرَهَا وَأَخْبَرَهَا أَنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَةِ فَقَالَتْ وَالَّذِي بَعَثَكَ بِالْحَقِّ إِنَّهُ لَكَاذِبٌ قَالَ فَبَدَأَ بِالرَّجُلِ فَشَهِدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنْ الصَّادِقِينَ وَالْخَامِسَةَ أَنَّ لَعْنَةَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنْ الْكَاذِبِينَ ثُمَّ ثَنَّى بِالْمَرْأَةِ فَشَهِدَتْ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنْ الْكَاذِبِينَ وَالْخَامِسَةَ أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنْ الصَّادِقِينَ ثُمَّ فَرَّقَ بَيْنَهُمَا ‏","","",""],[4465,4465,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا طَلَعَ حَاجِبُ الشَّمْسِ فَأَخِّرُوا الصَّلَاةَ حَتَّى تَبْرُزَ فَإِذَا غَابَ حَاجِبُ الشَّمْسِ فَأَخِّرُوا الصَّلَاةَ حَتَّى تَغِيبَ ‏","","",""],[4466,4466,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَحَرَّوْا ‏ ‏بِصَلَاتِكُمْ طُلُوعَ الشَّمْسِ وَلَا غُرُوبَهَا فَإِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ ‏","","",""],[4467,4467,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُسَافِرْ الْمَرْأَةُ ثَلَاثًا إِلَّا وَمَعَهَا ذُو ‏ ‏مَحْرَمٍ ‏","","",""],[4468,4468,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ ‏} ‏قَالَ يَقُومُ فِي ‏ ‏رَشْحِهِ ‏ ‏إِلَى أَنْصَافِ أُذُنَيْهِ ‏","","",""],[4469,4469,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الْيَهُودَ ‏ ‏إِذَا سَلَّمُوا فَإِنَّمَا تَقُولُ ‏ ‏السَّامُ ‏ ‏عَلَيْكَ فَقُلْ عَلَيْكَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏ ‏مِثْلَهُ ‏","","",""],[4470,4470,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏أَنَّ نَاسًا دَخَلُوا عَلَى ‏ ‏ابْنِ عَامَرٍ ‏ ‏فِي مَرَضِهِ فَجَعَلُوا ‏ ‏يُثْنُونَ ‏ ‏عَلَيْهِ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَمَا إِنِّي لَسْتُ ‏ ‏بِأَغَشِّهِمْ لَكَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى لَا يَقْبَلُ ‏ ‏صَدَقَةً ‏ ‏مِنْ ‏ ‏غُلُولٍ ‏ ‏وَلَا صَلَاةً بِغَيْرِ طُهُورٍ ‏","","",""],[4471,4471,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّرَ ‏ ‏أُسَامَةَ ‏ ‏عَلَى قَوْمٍ فَطَعَنَ النَّاسُ فِي ‏ ‏إِمَارَتِهِ ‏ ‏فَقَالَ إِنْ تَطْعَنُوا فِي ‏ ‏إِمَارَتِهِ ‏ ‏فَقَدْ طَعَنْتُمْ فِي ‏ ‏إِمَارَةِ ‏ ‏أَبِيهِ وَايْمُ اللَّهِ إِنْ كَانَ لَخَلِيقًا لِلْإِمَارَةِ وَإِنْ كَانَ لَمِنْ أَحَبِّ النَّاسِ إِلَيَّ وَإِنَّ ابْنَهُ هَذَا لَأَحَبُّ النَّاسِ إِلَيَّ بَعْدَهُ ‏","","",""],[4472,4472,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏ ‏وَغِفَارٌ ‏ ‏غَفَرَ اللَّهُ لَهَا ‏ ‏وَعُصَيَّةُ ‏ ‏عَصَتْ اللَّهَ وَرَسُولَهُ ‏","","",""],[4473,4473,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏قُرَيْشٌ ‏ ‏تَحْلِفُ بِآبَائِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ حَالِفًا فَلْيَحْلِفْ بِاللَّهِ لَا تَحْلِفُوا بِآبَائِكُمْ ‏","","",""],[4474,4474,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏أَبِي حَنْظَلَةَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏عَنْ الصَّلَاةِ فِي السَّفَرِ قَالَ ‏ ‏الصَّلَاةُ فِي السَّفَرِ رَكْعَتَانِ قُلْنَا إِنَّا آمِنُونَ قَالَ سُنَّةُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4475,4475,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَالَ ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏مَرَّةً ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏نَذَرْتُ فِي الْجَاهِلِيَّةِ أَنْ أَعْتَكِفَ لَيْلَةً فِي الْمَسْجِدِ فَقَالَ وَفِّ بِنَذْرِكَ ‏","","",""],[4476,4476,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا نَصَحَ الْعَبْدُ لِسَيِّدِهِ وَأَحْسَنَ عِبَادَةَ رَبِّهِ لَهُ الْأَجْرُ مَرَّتَيْنِ ‏","","",""],[4477,4477,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الَّذِينَ يَصْنَعُونَ هَذِهِ الصُّوَرَ يُعَذَّبُونَ وَيُقَالُ لَهُمْ أَحْيُوا مَا خَلَقْتُمْ ‏","","",""],[4478,4478,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏التَّلَقِّي ‏","","",""],[4479,4479,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا وُضِعَ عَشَاءُ أَحَدِكُمْ وَأُقِيمَتْ الصَّلَاةُ فَلَا يَقُومُ حَتَّى يَفْرُغَ ‏","","",""],[4480,4480,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اجْعَلُوا آخِرَ صَلَاتِكُمْ بِاللَّيْلِ وِتْرًا ‏","","",""],[4481,4481,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏خَالِهِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَتْ تَحْتِي امْرَأَةٌ كَانَ ‏ ‏عُمَرُ ‏ ‏يَكْرَهُهَا فَقَالَ ‏ ‏طَلِّقْهَا فَأَبَيْتُ فَأَتَى ‏ ‏عُمَرُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَطِعْ أَبَاكَ ‏","","",""],[4482,4482,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نُودِيَ أَحَدُكُمْ إِلَى ‏ ‏وَلِيمَةٍ ‏ ‏فَلْيَأْتِهَا ‏","","",""],[4483,4483,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَأَى ‏ ‏حُلَّةَ ‏ ‏سِيَرَاءَ ‏ ‏أَوْ حَرِيرٍ ‏ ‏تُبَاعُ فَقَالَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ اشْتَرَيْتَ هَذِهِ تَلْبَسُهَا يَوْمَ الْجُمُعَةِ أَوْ لِلْوُفُودِ قَالَ ‏ ‏إِنَّمَا يَلْبَسُ هَذِهِ مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ قَالَ فَأُهْدِيَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهَا ‏ ‏حُلَلٌ ‏ ‏فَبَعَثَ إِلَى ‏ ‏عُمَرَ ‏ ‏مِنْهَا ‏ ‏بِحُلَّةٍ ‏ ‏قَالَ سَمِعْتُ مِنْكَ تَقُولُ مَا قُلْتَ وَبَعَثْتَ إِلَيَّ بِهَا قَالَ إِنَّمَا بَعَثْتُ بِهَا إِلَيْكَ لِتَبِيعَهَا أَوْ تَكْسُوَهَا ‏","","",""],[4484,4484,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ جُبَيْرٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏مُقْبِلًا مِنْ ‏ ‏مَكَّةَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏حَيْثُ تَوَجَّهَتْ بِهِ وَفِيهِ نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏فَأَيْنَمَا ‏ ‏تُوَلُّوا ‏ ‏فَثَمَّ وَجْهُ اللَّهِ ‏}","","",""],[4485,4485,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَكَلَ مِنْ هَذِهِ ‏ ‏الشَّجَرَةِ فَلَا يَأْتِيَنَّ الْمَسَاجِدَ ‏","","",""],[4486,4486,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانُوا يَتَبَايَعُونَ الطَّعَامَ ‏ ‏جُزَافًا ‏ ‏بِأَعْلَى السُّوقِ ‏ ‏فَنَهَاهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَبِيعُوهُ حَتَّى يَنْقُلُوهُ ‏","","",""],[4487,4487,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏قَفَلَ ‏ ‏مِنْ الْجُيُوشِ أَوْ السَّرَايَا أَوْ الْحَجِّ أَوْ الْعُمْرَةِ ‏ ‏أَوْ ‏ ‏إِذَا ‏ ‏أَوْفَى ‏ ‏عَلَى ‏ ‏ثَنِيَّةٍ ‏ ‏أَوْ ‏ ‏فَدْفَدٍ ‏ ‏كَبَّرَ ثَلَاثًا وَيَقُولُ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏ ‏آيِبُونَ ‏ ‏تَائِبُونَ عَابِدُونَ سَاجِدُونَ لِرَبِّنَا حَامِدُونَ صَدَقَ اللَّهُ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ ‏","","",""],[4488,4488,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ ‏","","",""],[4489,4489,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحُمَّى ‏ ‏مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ فَأَبْرِدُوهَا بِالْمَاءِ ‏","","",""],[4490,4490,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏عَنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ ‏","","",""],[4491,4491,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏وَاصَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي رَمَضَانَ ‏ ‏فَوَاصَلَ ‏ ‏النَّاسُ فَقَالُوا نَهَيْتَنَا عَنْ ‏ ‏الْوِصَالِ ‏ ‏وَأَنْتَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ ‏ ‏إِنِّي لَسْتُ كَأَحَدٍ مِنْكُمْ إِنِّي أُطْعَمُ وَأُسْقَى ‏","","",""],[4492,4492,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَبِعْ أَحَدُكُمْ عَلَى بَيْعِ أَخِيهِ وَلَا يَخْطُبْ عَلَى خِطْبَةِ أَخِيهِ إِلَّا أَنْ ‏ ‏يَأْذَنَ ‏ ‏لَهُ ‏","","",""],[4493,4493,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَمَامَكُمْ حَوْضًا مَا بَيْنَ ‏ ‏جَرْبَاءَ ‏ ‏وَأَذْرُحَ ‏","","",""],[4494,4494,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏ ‏وَالْوَاشِمَةَ ‏ ‏وَالْمُسْتَوْشِمَةَ ‏","","",""],[4495,4495,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏مِنْ ‏ ‏الثَّنِيَّةِ الْعُلْيَا ‏ ‏الَّتِي ‏ ‏بِالْبَطْحَاءِ ‏ ‏وَخَرَجَ مِنْ ‏ ‏الثَّنِيَّةِ السُّفْلَى ‏","","",""],[4496,4496,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ يَعْنِي ابْنَ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سُوقَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏إِنْ كُنَّا لَنَعُدُّ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَجْلِسِ يَقُولُ ‏ ‏رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ مِائَةَ مَرَّةٍ ‏","","",""],[4497,4497,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلٌ يَعْنِي ابْنَ غَزْوَانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى ‏ ‏فَاطِمَةَ ‏ ‏فَوَجَدَ عَلَى بَابِهَا سِتْرًا فَلَمْ يَدْخُلْ عَلَيْهَا وَقَلَّمَا كَانَ يَدْخُلُ إِلَّا بَدَأَ بِهَا قَالَ فَجَاءَ ‏ ‏عَلِيٌّ ‏ ‏فَرَآهَا مُهْتَمَّةً فَقَالَ مَا لَكِ فَقَالَتْ جَاءَ إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَدْخُلْ عَلَيَّ فَأَتَاهُ ‏ ‏عَلِيٌّ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏فَاطِمَةَ ‏ ‏اشْتَدَّ ‏ ‏عَلَيْهَا أَنَّكَ جِئْتَهَا فَلَمْ تَدْخُلْ عَلَيْهَا فَقَالَ ‏ ‏وَمَا أَنَا وَالدُّنْيَا وَمَا أَنَا ‏ ‏وَالرَّقْمُ ‏ ‏قَالَ فَذَهَبَ إِلَى ‏ ‏فَاطِمَةَ ‏ ‏فَأَخْبَرَهَا بِقَوْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ فَقُلْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا تَأْمُرُنِي بِهِ فَقَالَ قُلْ لَهَا تُرْسِلُ بِهِ إِلَى بَنِي فُلَانٍ ‏","","",""],[4498,4498,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلٌ يَعْنِي ابْنَ غَزْوَانَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو دُهْقَانَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا عِنْدَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏فَقَالَ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَيْفٌ فَقَالَ ‏ ‏لِبِلَالٍ ‏ ‏ائْتِنَا بِطَعَامٍ فَذَهَبَ ‏ ‏بِلَالٌ ‏ ‏فَأَبْدَلَ ‏ ‏صَاعَيْنِ ‏ ‏مِنْ تَمْرٍ ‏ ‏بِصَاعٍ ‏ ‏مِنْ تَمْرٍ جَيِّدٍ وَكَانَ تَمْرُهُمْ دُونًا فَأَعْجَبَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّمْرُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَيْنَ هَذَا التَّمْرُ فَأَخْبَرَهُ أَنَّهُ أَبْدَلَ ‏ ‏صَاعًا ‏ ‏بِصَاعَيْنِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُدَّ ‏ ‏عَلَيْنَا تَمْرَنَا ‏","","",""],[4499,4499,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا لَمْ يَشْرَبْهَا فِي الْآخِرَةِ إِلَّا أَنْ يَتُوبَ ‏","","",""],[4500,4500,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا دُعِيَ أَحَدُكُمْ إِلَى ‏ ‏وَلِيمَةِ ‏ ‏عُرْسٍ فَلْيُجِبْ ‏","","",""],[4501,4501,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنَ ‏ ‏الْعَبَّاسُ بْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يَبِيتَ ‏ ‏بِمَكَّةَ ‏ ‏لَيَالِيَ ‏ ‏مِنًى ‏ ‏مِنْ أَجْلِ ‏ ‏سِقَايَتِهِ ‏ ‏فَأَذِنَ لَهُ ‏","","",""],[4502,4502,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَلَ أَهْلَ ‏ ‏خَيْبَرَ ‏ ‏بِشَطْرِ ‏ ‏مَا خَرَجَ مِنْ زَرْعٍ أَوْ تَمْرٍ فَكَانَ يُعْطِي أَزْوَاجَهُ كُلَّ عَامٍ مِائَةَ ‏ ‏وَسْقٍ ‏ ‏وَثَمَانِينَ ‏ ‏وَسْقًا ‏ ‏مِنْ تَمْرٍ وَعِشْرِينَ ‏ ‏وَسْقًا ‏ ‏مِنْ شَعِيرٍ فَلَمَّا قَامَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏قَسَمَ ‏ ‏خَيْبَرَ ‏ ‏فَخَيَّرَ أَزْوَاجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُقْطِعَ ‏ ‏لَهُنَّ مِنْ الْأَرْضِ أَوْ يَضْمَنَ لَهُنَّ ‏ ‏الْوُسُوقَ ‏ ‏كُلَّ عَامٍ فَاخْتَلَفُوا فَمِنْهُنَّ مَنْ اخْتَارَ أَنْ ‏ ‏يُقْطِعَ ‏ ‏لَهَا الْأَرْضَ وَمِنْهُنَّ مَنْ اخْتَارَ ‏ ‏الْوُسُوقَ ‏ ‏وَكَانَتْ ‏ ‏حَفْصَةُ ‏ ‏وَعَائِشَةُ ‏ ‏مِمَّنْ اخْتَارَ ‏ ‏الْوُسُوقَ ‏","","",""],[4503,4503,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏غَدَوْنَا ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏مِنًى ‏ ‏إِلَى ‏ ‏عَرَفَاتٍ ‏ ‏مِنَّا الْمُلَبِّي وَمِنَّا الْمُكَبِّرُ ‏","","",""],[4504,4504,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏اتَّخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا مِنْ ‏ ‏وَرِقٍ ‏ ‏فَكَانَ فِي يَدِهِ ثُمَّ كَانَ فِي يَدِ ‏ ‏أَبِي بَكْرٍ ‏ ‏مِنْ بَعْدِهِ ثُمَّ كَانَ فِي يَدِ ‏ ‏عُمَرَ ‏ ‏ثُمَّ كَانَ فِي يَدِ ‏ ‏عُثْمَانَ ‏ ‏نَقْشُهُ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4505,4505,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُقِيمُ الرَّجُلُ الرَّجُلَ عَنْ مَقْعَدِهِ يَقْعُدُ فِيهِ وَلَكِنْ تَفَسَّحُوا وَتَوَسَّعُوا ‏","","",""],[4506,4506,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اشْتَرَى طَعَامًا فَلَا يَبِعْهُ حَتَّى ‏ ‏يَسْتَوْفِيَهُ ‏","","",""],[4507,4507,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏وَبَرَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَتْلِ الْفَأْرَةِ وَالْغُرَابِ وَالذِّئْبِ قَالَ قِيلَ ‏ ‏لِابْنِ عُمَرَ ‏ ‏الْحَيَّةُ وَالْعَقْرَبُ قَالَ قَدْ كَانَ يُقَالُ ذَلِكَ ‏","","",""],[4508,4508,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏تُتَلَقَّى السِّلَعُ حَتَّى تَدْخُلَ الْأَسْوَاقَ ‏","","",""],[4509,4509,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى فِي بَعْضِ مَغَازِيهِ امْرَأَةً مَقْتُولَةً ‏ ‏فَنَهَى عَنْ قَتْلِ النِّسَاءِ وَالصِّبْيَانِ ‏","","",""],[4510,4510,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى النِّسَاءَ فِي الْإِحْرَامِ عَنْ الْقُفَّازِ وَالنِّقَابِ وَمَا مَسَّ ‏ ‏الْوَرْسُ ‏ ‏وَالزَّعْفَرَانُ ‏ ‏مِنْ الثِّيَابِ ‏","","",""],[4511,4511,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نَعَسَ أَحَدُكُمْ فِي مَجْلِسِهِ يَوْمَ الْجُمُعَةِ فَلْيَتَحَوَّلْ إِلَى غَيْرِهِ ‏","","",""],[4512,4512,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الَّذِي يَكْذِبُ عَلَيَّ ‏ ‏يُبْنَى لَهُ بَيْتٌ فِي النَّارِ ‏","","",""],[4513,4513,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ عِنْدَ ‏ ‏الْكَعْبَةِ ‏ ‏رَجُلًا ‏ ‏آدَمَ ‏ ‏سَبْطَ ‏ ‏الرَّأْسِ وَاضِعًا يَدَهُ عَلَى رَجُلَيْنِ ‏ ‏يَسْكُبُ ‏ ‏رَأْسُهُ ‏ ‏أَوْ يَقْطُرُ رَأْسُهُ ‏ ‏فَسَأَلْتُ مَنْ هَذَا فَقَالُوا ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏أَوْ ‏ ‏الْمَسِيحُ ابْنُ مَرْيَمَ ‏ ‏وَلَا أَدْرِي أَيَّ ذَلِكَ قَالَ ‏ ‏وَرَأَيْتُ وَرَاءَهُ رَجُلًا أَحْمَرَ ‏ ‏جَعْدَ ‏ ‏الرَّأْسِ أَعْوَرَ عَيْنِ الْيُمْنَى ‏ ‏أَشْبَهُ ‏ ‏مَنْ رَأَيْتُ بِهِ ‏ ‏ابْنُ قَطَنٍ ‏ ‏فَسَأَلْتُ مَنْ هَذَا فَقَالُوا ‏ ‏الْمَسِيحُ الدَّجَّالُ ‏","","",""],[4514,4514,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الْحَفَرِيُّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِقَتْلِ الْكِلَابِ حَتَّى ‏ ‏قَتَلْنَا كَلْبَ امْرَأَةٍ جَاءَتْ مِنْ ‏ ‏الْبَادِيَةِ ‏","","",""],[4515,4515,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلٌ يَعْنِي ابْنَ غَزْوَانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا رَجُلٍ كَفَّرَ رَجُلًا فَإِنْ كَانَ كَمَا قَالَ وَإِلَّا فَقَدْ ‏ ‏بَاءَ ‏ ‏بِالْكُفْرِ ‏","","",""],[4516,4516,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏أَنْبَأَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى فِي بَعْضِ مَغَازِيهِ امْرَأَةً مَقْتُولَةً فَأَنْكَرَ ذَاكَ ‏ ‏وَنَهَى عَنْ قَتْلِ النِّسَاءِ وَالصِّبْيَانِ ‏","","",""],[4517,4517,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏مَوْلَى ‏ ‏طَلْحَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَقَدْ سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثًا لَوْ لَمْ أَسْمَعْهُ إِلَّا مَرَّةً أَوْ مَرَّتَيْنِ حَتَّى عَدَّ سَبْعَ مِرَارٍ وَلَكِنْ قَدْ سَمِعْتُهُ أَكْثَرَ مِنْ ذَلِكَ قَالَ ‏ ‏كَانَ الْكِفْلُ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏لَا ‏ ‏يَتَوَرَّعُ ‏ ‏مِنْ ذَنْبٍ عَمِلَهُ فَأَتَتْهُ امْرَأَةٌ فَأَعْطَاهَا سِتِّينَ دِينَارًا عَلَى أَنْ ‏ ‏يَطَأَهَا ‏ ‏فَلَمَّا قَعَدَ مِنْهَا مَقْعَدَ الرَّجُلِ مِنْ امْرَأَتِهِ ‏ ‏أَرْعَدَتْ ‏ ‏وَبَكَتْ فَقَالَ مَا يُبْكِيكِ أَكْرَهْتُكِ قَالَتْ لَا وَلَكِنْ هَذَا عَمَلٌ لَمْ أَعْمَلْهُ قَطُّ وَإِنَّمَا حَمَلَنِي عَلَيْهِ ‏ ‏الْحَاجَةُ ‏ ‏قَالَ فَتَفْعَلِينَ هَذَا وَلَمْ تَفْعَلِيهِ قَطُّ قَالَ ثُمَّ نَزَلَ فَقَالَ اذْهَبِي فَالدَّنَانِيرُ لَكِ ثُمَّ قَالَ وَاللَّهِ لَا يَعْصِي اللَّهَ الْكِفْلُ أَبَدًا فَمَاتَ مِنْ لَيْلَتِهِ فَأَصْبَحَ مَكْتُوبًا عَلَى بَابِهِ قَدْ غَفَرَ اللَّهُ عَزَّ وَجَلَّ لِلْكِفْلِ ‏","","",""],[4518,4518,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ يَعْلَمُ النَّاسُ مَا فِي الْوَحْدَةِ مَا سَارَ أَحَدٌ وَحْدَهُ بِلَيْلٍ أَبَدًا ‏","","",""],[4519,4519,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏زَيْدٍ الْعَمِّىِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَرَادَ أَنْ تُسْتَجَابَ دَعْوَتُهُ وَأَنْ تُكْشَفَ ‏ ‏كُرْبَتُهُ ‏ ‏فَلْيُفَرِّجْ عَنْ مُعْسِرٍ ‏","","",""],[4520,4520,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏قَبَّلَ يَدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4521,4521,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ بَيْتِ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَ ‏ ‏رَأْسُ الْكُفْرِ مِنْ هَاهُنَا مِنْ حَيْثُ يَطْلُعُ قَرْنُ الشَّيْطَانِ ‏","","",""],[4522,4522,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْعُمَرِيِّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْوِصَالِ ‏ ‏فِي الصِّيَامِ فَقِيلَ لَهُ إِنَّكَ تَفْعَلُهُ فَقَالَ إِنِّي لَسْتُ كَأَحَدِكُمْ إِنِّي أَظَلُّ يُطْعِمُنِي رَبِّي وَيَسْقِينِي ‏","","",""],[4523,4523,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ الْمَاءُ قَدْرَ ‏ ‏قُلَّتَيْنِ ‏ ‏أَوْ ثَلَاثٍ لَمْ يُنَجِّسْهُ شَيْءٌ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏يَعْنِي بِالْقُلَّةِ الْجَرَّةَ ‏","","",""],[4524,4524,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَجِيءُ ‏ ‏الْفِتْنَةُ ‏ ‏مِنْ هَاهُنَا مِنْ الْمَشْرِقِ ‏","","",""],[4525,4525,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَنَابٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ هَذِهِ ‏ ‏السَّارِيَةِ ‏ ‏وَهِيَ يَوْمَئِذٍ ‏ ‏جِذْعُ ‏ ‏نَخْلَةٍ ‏ ‏يَعْنِي يَخْطُبُ ‏","","",""],[4526,4526,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏قُدَامَةُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا صَلَاةَ بَعْدَ طُلُوعِ الْفَجْرِ إِلَّا رَكْعَتَيْنِ ‏","","",""],[4527,4527,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَالْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ فِي بَيْتِهِ ‏","","",""],[4528,4528,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏تَوْبَةَ الْعَنْبَرِيِّ ‏ ‏عَنْ ‏ ‏مُوَرِّقٍ الْعِجْلِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَتُصَلِّي الضُّحَى قَالَ لَا قُلْتُ ‏ ‏فَصَلَّاهَا ‏ ‏عُمَرُ ‏ ‏قَالَ لَا قُلْتُ صَلَّاهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏قَالَ لَا قُلْتُ ‏ ‏أَصَلَّاهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا ‏ ‏إِخَالُهُ ‏","","",""],[4529,4529,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْقُرْآنِ مَثَلُ الْإِبِلِ ‏ ‏الْمُعَقَّلَةِ ‏ ‏إِنْ تَعَاهَدَهَا صَاحِبُهَا أَمْسَكَهَا وَإِنْ تَرَكَهَا ذَهَبَتْ ‏","","",""],[4530,4530,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي عَاصِمٍ الثَّقَفِيِّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الصَّلَاةِ ‏ ‏بِمِنًى ‏ ‏فَقَالَ هَلْ سَمِعْتَ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ نَعَمْ وَآمَنْتُ فَاهْتَدَيْتُ بِهِ قَالَ ‏ ‏فَإِنَّهُ كَانَ ‏ ‏يُصَلِّي ‏ ‏بِمِنًى ‏ ‏رَكْعَتَيْنِ ‏","","",""],[4531,4531,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَصَلَّيْنَا الْفَرِيضَةَ فَرَأَى بَعْضَ وَلَدِهِ يَتَطَوَّعُ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏فِي السَّفَرِ فَلَمْ يُصَلُّوا قَبْلَهَا وَلَا بَعْدَهَا ‏ ‏قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَلَوْ تَطَوَّعْتُ لَأَتْمَمْتُ ‏","","",""],[4532,4532,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَعَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُلْحِدَ ‏ ‏لَهُ ‏ ‏لَحْدٌ ‏","","",""],[4533,4533,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَ فِي الرَّكْعَتَيْنِ قَبْلَ الْفَجْرِ وَالرَّكْعَتَيْنِ بَعْدَ الْمَغْرِبِ بِضْعًا وَعِشْرِينَ مَرَّةً ‏ ‏أَوْ بِضْعَ عَشْرَةَ مَرَّةً ‏ ‏قُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏","","",""],[4534,4534,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِبَعْضِ جَسَدِي فَقَالَ يَا ‏ ‏عَبْدَ اللَّهِ ‏ ‏كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ وَاعْدُدْ نَفْسَكَ فِي الْمَوْتَى ‏","","",""],[4535,4535,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏عِمْرَانُ بْنُ حُدَيْرٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عُطَارِدٍ أَبِي الْبَزَرَى السَّدُوسِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا نَشْرَبُ وَنَحْنُ قِيَامٌ وَنَأْكُلُ وَنَحْنُ ‏ ‏نَسْعَى عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4536,4536,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَفَاتِيحُ الْغَيْبِ خَمْسٌ لَا يَعْلَمُهَا إِلَّا اللَّهُ ‏ { ‏إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ ‏ ‏الْغَيْثَ ‏ ‏وَيَعْلَمُ مَا فِي الْأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ ‏}","","",""],[4537,4537,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏عُيَيْنَةُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدِ بْنِ جُدْعَانَ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا يَلْبَسُ الْحَرِيرَ مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ ‏","","",""],[4538,4538,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏ابْنَ رَوَاحَةَ ‏ ‏إِلَى ‏ ‏خَيْبَرَ ‏ ‏يَخْرُصُ ‏ ‏عَلَيْهِمْ ثُمَّ خَيَّرَهُمْ أَنْ يَأْخُذُوا أَوْ يَرُدُّوا فَقَالُوا هَذَا الْحَقُّ بِهَذَا قَامَتْ السَّمَوَاتُ وَالْأَرْضُ ‏","","",""],[4539,4539,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏إِخْصَاءِ ‏ ‏الْخَيْلِ وَالْبَهَائِمِ ‏ ‏و قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فِيهَا نَمَاءُ الْخَلْقِ ‏","","",""],[4540,4540,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ يَعْلَمُ النَّاسُ مَا فِي الْوَحْدَةِ مَا سَارَ ‏ ‏رَاكِبٌ ‏ ‏بِلَيْلٍ وَحْدَهُ أَبَدًا ‏","","",""],[4541,4541,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ الْهُجَيْمِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏فَلَا صَلَاةَ بَعْدَ ‏ ‏الْغَدَاةِ ‏ ‏حَتَّى تَطْلُعَ ‏ ‏يَعْنِي الشَّمْسَ ‏","","",""],[4542,4542,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَحَرَّوْا ‏ ‏بِصَلَاتِكُمْ طُلُوعَ الشَّمْسِ وَلَا غُرُوبَهَا فَإِنَّهَا تَطْلُعُ بَيْنَ ‏ ‏قَرْنَيْ شَيْطَانٍ ‏","","",""],[4543,4543,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ لِلنِّسَاءِ أَنْ يُرْخِينَ شِبْرًا فَقُلْنَ يَا رَسُولَ اللَّهِ إِذَنْ تَنْكَشِفَ أَقْدَامُنَا فَقَالَ ذِرَاعًا وَلَا تَزِدْنَ عَلَيْهِ ‏","","",""],[4544,4544,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ أَحْسَنِ أَسْمَائِكُمْ ‏ ‏عَبْدَ اللَّهِ ‏ ‏وَعَبْدَ الرَّحْمَنِ ‏","","",""],[4545,4545,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَنَابٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏عَدْوَى ‏ ‏وَلَا ‏ ‏طِيَرَةَ ‏ ‏وَلَا ‏ ‏هَامَةَ ‏ ‏قَالَ فَقَامَ إِلَيْهِ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ الْبَعِيرَ يَكُونُ بِهِ الْجَرَبُ فَتَجْرَبُ الْإِبِلُ قَالَ ذَلِكَ ‏ ‏الْقَدَرُ ‏ ‏فَمَنْ أَجْرَبَ الْأَوَّلَ ‏","","",""],[4546,4546,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏رَزِينِ بْنِ سُلَيْمَانَ الْأَحْمَرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الرَّجُلِ يُطَلِّقُ امْرَأَتَهُ ثَلَاثًا فَيَتَزَوَّجُهَا آخَرُ فَيُغْلَقُ الْبَابُ ‏ ‏وَيُرْخَى السِّتْرُ ثُمَّ يُطَلِّقُهَا قَبْلَ أَنْ يَدْخُلَ بِهَا هَلْ تَحِلُّ لِلْأَوَّلِ قَالَ ‏ ‏لَا حَتَّى يَذُوقَ ‏ ‏الْعُسَيْلَةَ ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو أَحْمَدُ يَعْنِي الزُّبَيْرِيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ رَزِينٍ ‏","","",""],[4547,4547,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ ‏ ‏مَكَّةَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ لَا تَجْعَلْ مَنَايَانَا بِهَا حَتَّى تُخْرِجَنَا مِنْهَا ‏","","",""],[4548,4548,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تُضْرَبَ الصُّوَرُ ‏ ‏يَعْنِي الْوَجْهَ ‏","","",""],[4549,4549,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَعْجَلْ أَحَدُكُمْ عَنْ طَعَامِهِ لِلصَّلَاةِ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَسْمَعُ الْإِقَامَةَ وَهُوَ ‏ ‏يَتَعَشَّى فَلَا يَعْجَلُ ‏","","",""],[4550,4550,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏ابْنُ عُمَرَ ‏ ‏أُوَدِّعُكَ كَمَا وَدَّعَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْتَوْدِعُ اللَّهَ دِينَكَ وَأَمَانَتَكَ وَخَوَاتِيمَ عَمَلِكَ ‏","","",""],[4551,4551,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعُ بْنُ عُمَرَ الْجُمَحِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ حَسَّانَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنْزِلُ ‏ ‏بِعَرَفَةَ ‏ ‏وَادِيَ نَمِرَةَ ‏ ‏فَلَمَّا قَتَلَ ‏ ‏الْحَجَّاجُ بْنَ الزُّبَيْرِ ‏ ‏أَرْسَلَ إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏أَيَّةَ سَاعَةٍ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرُوحُ فِي هَذَا الْيَوْمِ فَقَالَ إِذَا كَانَ ذَاكَ رُحْنَا فَأَرْسَلَ ‏ ‏الْحَجَّاجُ ‏ ‏رَجُلًا يَنْظُرُ أَيَّ سَاعَةٍ يَرُوحُ فَلَمَّا أَرَادَ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنْ يَرُوحَ قَالَ ‏ ‏أَزَاغَتْ ‏ ‏الشَّمْسُ قَالُوا لَمْ ‏ ‏تَزِغْ ‏ ‏الشَّمْسُ قَالَ ‏ ‏زَاغَتْ ‏ ‏الشَّمْسُ قَالُوا لَمْ ‏ ‏تَزِغْ ‏ ‏فَلَمَّا قَالُوا قَدْ ‏ ‏زَاغَتْ ‏ ‏ارْتَحَلَ ‏","","",""],[4552,4552,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏فَرْقَدٍ السَّبَخِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَدَّهِنُ عِنْدَ الْإِحْرَامِ بِالزَّيْتِ غَيْرَ ‏ ‏الْمُقَتَّتِ ‏","","",""],[4553,4553,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ دَعَا غُلَامًا لَهُ فَأَعْتَقَهُ فَقَالَ مَا لِي مِنْ أَجْرِهِ مِثْلُ هَذَا لِشَيْءٍ رَفَعَهُ مِنْ الْأَرْضِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ لَطَمَ غُلَامَهُ فَكَفَّارَتُهُ عِتْقُهُ ‏","","",""],[4554,4554,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَادَةُ بْنُ مُسْلِمٍ الْفَزَارِيُّ ‏ ‏حَدَّثَنِي ‏ ‏جُبَيْرُ بْنُ أَبِي سُلَيْمَانَ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏لَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَعُ هَؤُلَاءِ الدَّعَوَاتِ حِينَ يُصْبِحُ وَحِينَ يُمْسِي ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي اللَّهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي وَمِنْ فَوْقِي وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي ‏ ‏قَالَ ‏ ‏يَعْنِي الْخَسْفَ ‏","","",""],[4555,4555,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏النَّجْرَانِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِسَكْرَانَ فَضَرَبَهُ ‏ ‏الْحَدَّ ‏ ‏فَقَالَ مَا شَرَابُكَ قَالَ الزَّبِيبُ وَالتَّمْرُ قَالَ ‏ ‏يَكْفِي كُلُّ وَاحِدٍ مِنْهُمَا مِنْ صَاحِبِهِ ‏","","",""],[4556,4556,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَبِي طُعْمَةَ ‏ ‏مَوْلَاهُمْ ‏ ‏وَعَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ الْغَافِقِيِّ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لُعِنَتْ الْخَمْرُ عَلَى عَشْرَةِ وُجُوهٍ لُعِنَتْ الْخَمْرُ بِعَيْنِهَا وَشَارِبُهَا وَسَاقِيهَا وَبَائِعُهَا ‏ ‏وَمُبْتَاعُهَا ‏ ‏وَعَاصِرُهَا وَمُعْتَصِرُهَا وَحَامِلُهَا وَالْمَحْمُولَةُ إِلَيْهِ وَآكِلُ ثَمَنِهَا ‏","","",""],[4557,4557,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُوسَى ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏نَرَى أَنَّهُ ‏ ‏ابْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏يَمِينُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّتِي يَحْلِفُ عَلَيْهَا لَا وَمُقَلِّبِ الْقُلُوبِ ‏","","",""],[4558,4558,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏مَوْلَى آلِ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ فَسَأَلَ ‏ ‏عُمَرُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مُرْهُ فَلْيُرَاجِعْهَا ثُمَّ لِيُطَلِّقْهَا طَاهِرًا أَوْ حَامِلًا ‏","","",""],[4559,4559,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُصْمٍ ‏ ‏وَقَالَ ‏ ‏إِسْرَائِيلُ ‏ ‏ابْنِ عِصْمَةَ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏هُوَ ‏ ‏ابْنُ عُصْمٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي ‏ ‏ثَقِيفَ ‏ ‏مُبِيرًا ‏ ‏وَكَذَّابًا ‏","","",""],[4560,4560,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ الْأَزْدِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةُ اللَّيْلِ وَالنَّهَارِ مَثْنَى مَثْنَى ‏","","",""],[4561,4561,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشَدُّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ الْمُصَوِّرُونَ يُقَالُ لَهُمْ أَحْيُوا مَا خَلَقْتُمْ ‏","","",""],[4562,4562,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى إِلَى بَعِيرِهِ ‏","","",""],[4563,4563,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏بَيْنَا النَّاسُ فِي ‏ ‏مَسْجِدِ قُبَاءَ ‏ ‏فِي صَلَاةِ الصُّبْحِ إِذْ أَتَاهُمْ ‏ ‏آتٍ ‏ ‏فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏نَزَلَ عَلَيْهِ قُرْآنٌ وَوُجِّهَ نَحْوَ ‏ ‏الْكَعْبَةِ ‏ ‏قَالَ فَانْحَرَفُوا ‏","","",""],[4564,4564,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي الْمُجَالِدِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏انْتَفَى ‏ ‏مِنْ وَلَدِهِ لِيَفْضَحَهُ فِي الدُّنْيَا فَضَحَهُ اللَّهُ يَوْمَ الْقِيَامَةِ عَلَى رُءُوسِ الْأَشْهَادِ ‏ ‏قِصَاصٌ ‏ ‏بِقِصَاصٍ ‏","","",""],[4565,4565,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏خَالِهِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُنَا بِالتَّخْفِيفِ وَإِنْ كَانَ لَيَؤُمُّنَا ‏ ‏بِالصَّافَّاتِ ‏","","",""],[4566,4566,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَسِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا نَقُولُ فِي زَمَنِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَسُولُ اللَّهِ خَيْرُ النَّاسِ ثُمَّ ‏ ‏أَبُو بَكْرٍ ‏ ‏ثُمَّ ‏ ‏عُمَرُ ‏ ‏وَلَقَدْ أُوتِيَ ‏ ‏ابْنُ أَبِي طَالِبٍ ‏ ‏ثَلَاثَ خِصَالٍ لَأَنْ تَكُونَ لِي وَاحِدَةٌ مِنْهُنَّ أَحَبُّ إِلَيَّ مِنْ ‏ ‏حُمْرِ النَّعَمِ ‏ ‏زَوَّجَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنَتَهُ وَوَلَدَتْ لَهُ وَسَدَّ الْأَبْوَابَ إِلَّا بَابَهُ فِي الْمَسْجِدِ وَأَعْطَاهُ الرَّايَةَ يَوْمَ ‏ ‏خَيْبَرَ ‏","","",""],[4567,4567,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ بِشْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ ‏ ‏شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَإِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَحَجِّ ‏ ‏الْبَيْتِ ‏ ‏وَصَوْمِ رَمَضَانَ قَالَ فَقَالَ لَهُ رَجُلٌ وَالْجِهَادُ فِي سَبِيلِ اللَّهِ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏الْجِهَادُ حَسَنٌ هَكَذَا حَدَّثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4568,4568,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الْيَقْظَانِ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَةٌ عَلَى ‏ ‏كُثْبَانِ ‏ ‏الْمِسْكِ ‏ ‏يَوْمَ الْقِيَامَةِ رَجُلٌ أَمَّ قَوْمًا وَهُمْ بِهِ رَاضُونَ وَرَجُلٌ يُؤَذِّنُ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ خَمْسَ صَلَوَاتٍ وَعَبْدٌ أَدَّى حَقَّ اللَّهِ تَعَالَى وَحَقَّ ‏ ‏مَوَالِيهِ ‏","","",""],[4569,4569,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو يَحْيَى الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى القَتَّاتِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَعْظُمُ أَهْلُ النَّارِ فِي النَّارِ حَتَّى إِنَّ بَيْنَ ‏ ‏شَحْمَةِ ‏ ‏أُذُنِ أَحَدِهِمْ إِلَى ‏ ‏عَاتِقِهِ ‏ ‏مَسِيرَةَ سَبْعِ مِائَةِ عَامٍ وَإِنَّ غِلَظَ جِلْدِهِ سَبْعُونَ ذِرَاعًا وَإِنَّ ضِرْسَهُ مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[4570,4570,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الرُّقْبَى ‏ ‏وَقَالَ مَنْ ‏ ‏أُرْقِبَ ‏ ‏فَهُوَ لَهُ ‏","","",""],[4571,4571,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ بَيْتِ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَ ‏ ‏إِنَّ الْكُفْرَ مِنْ هَاهُنَا مِنْ حَيْثُ يَطْلُعُ قَرْنُ الشَّيْطَانِ ‏","","",""],[4572,4572,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُسْأَلُ عَنْ الْمَاءِ يَكُونُ ‏ ‏بِالْفَلَاةِ ‏ ‏مِنْ الْأَرْضِ وَمَا ‏ ‏يَنُوبُهُ ‏ ‏مِنْ الدَّوَابِّ وَالسِّبَاعِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ الْمَاءُ ‏ ‏قُلَّتَيْنِ ‏ ‏لَمْ يُنَجِّسْهُ شَيْءٌ ‏","","",""],[4573,4573,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ ‏ ‏لَمْ يَكُنْ نَبِيٌّ قَبْلِي إِلَّا وَصَفَهُ لِأُمَّتِهِ وَلَأَصِفَنَّهُ صِفَةً لَمْ يَصِفْهَا مَنْ كَانَ قَبْلِي إِنَّهُ أَعْوَرُ وَاللَّهُ تَبَارَكَ وَتَعَالَى لَيْسَ بِأَعْوَرَ عَيْنُهُ الْيُمْنَى كَأَنَّهَا عِنَبَةٌ طَافِيَةٌ ‏","","",""],[4574,4574,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنِ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَرَكَ الْعَصْرَ مُتَعَمِّدًا حَتَّى تَغْرُبَ الشَّمْسُ فَكَأَنَّمَا ‏ ‏وُتِرَ ‏ ‏أَهْلَهُ وَمَالَهُ ‏","","",""],[4575,4575,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَحِيرٍ الصَّنْعَانِيُّ الْقَاصُّ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ يَزِيدَ الصَّنْعَانِيَّ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى يَوْمِ الْقِيَامَةِ كَأَنَّهُ رَأْيُ عَيْنٍ فَلْيَقْرَأْ ‏ ‏إِذَا الشَّمْسُ ‏ ‏كُوِّرَتْ ‏ ‏وَإِذَا السَّمَاءُ انْفَطَرَتْ ‏ ‏وَإِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏وَأَحْسَبُهُ أَنَّهُ قَالَ سُورَةَ ‏ ‏هُودٍ ‏","","",""],[4576,4576,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ يَعْنِي ابْنَ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏تَأَيَّمَتْ ‏ ‏حَفْصَةُ ‏ ‏وَكَانَتْ تَحْتَ ‏ ‏خُنَيْسِ بْنِ حُذَافَةَ ‏ ‏لَقِيَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏عُثْمَانَ ‏ ‏فَعَرَضَهَا عَلَيْهِ فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏مَا لِي فِي النِّسَاءِ حَاجَةٌ وَسَأَنْظُرُ فَلَقِيَ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَعَرَضَهَا عَلَيْهِ فَسَكَتَ فَوَجَدَ ‏ ‏عُمَرُ ‏ ‏فِي نَفْسِهِ عَلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ خَطَبَهَا فَلَقِيَ ‏ ‏عُمَرُ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَقَالَ إِنِّي كُنْتُ عَرَضْتُهَا عَلَى ‏ ‏عُثْمَانَ ‏ ‏فَرَدَّنِي وَإِنِّي عَرَضْتُهَا عَلَيْكَ فَسَكَتَّ عَنِّي فَلَأَنَا عَلَيْكَ كُنْتُ أَشَدَّ غَضَبًا مِنِّي عَلَى ‏ ‏عُثْمَانَ ‏ ‏وَقَدْ رَدَّنِي فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏إِنَّهُ قَدْ كَانَ ذَكَرَ مِنْ أَمْرِهَا وَكَانَ سِرًّا فَكَرِهْتُ أَنْ أُفْشِيَ السِّرَّ ‏","","",""],[4577,4577,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بَنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ ‏ ‏مُتَحَرِّيَهَا ‏ ‏فَلْيَتَحَرَّهَا ‏ ‏لَيْلَةَ سَبْعٍ وَعِشْرِينَ وَقَالَ تَحَرَّوْهَا لَيْلَةَ سَبْعٍ وَعِشْرِينَ ‏ ‏يَعْنِي لَيْلَةَ الْقَدْرِ ‏","","",""],[4578,4578,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ سُحَيْمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْحَنْتَمَةِ ‏ ‏قِيلَ وَمَا ‏ ‏الْحَنْتَمَةِ ‏ ‏قَالَ الْجَرَّةُ ‏ ‏يَعْنِي ‏ ‏النَّبِيذَ ‏","","",""],[4579,4579,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُسَيْنُ بْنُ ذَكْوَانَ يَعْنِي الْمُعَلِّمَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَابْنَ عَبَّاسٍ ‏ ‏رَفَعَاهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَحِلُّ لِرَجُلٍ أَنْ يُعْطِيَ الْعَطِيَّةَ فَيَرْجِعَ فِيهَا إِلَّا الْوَالِدَ فِيمَا يُعْطِي وَلَدَهُ وَمَثَلُ الَّذِي يُعْطِي الْعَطِيَّةَ ثُمَّ يَرْجِعُ فِيهَا كَمَثَلِ الْكَلْبِ أَكَلَ حَتَّى إِذَا شَبِعَ ‏ ‏قَاءَ ‏ ‏ثُمَّ رَجَعَ فِي ‏ ‏قَيْئِهِ ‏","","",""],[4580,4580,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ عَمْرِو الْجُمَحِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ بْنِ مُوسَى ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏فَمَرَّتْ رُفْقَةٌ لِأُمِّ الْبَنِينَ فِيهَا أَجْرَاسٌ ‏ ‏فَحَدَّثَ ‏ ‏سَالِمٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ ‏ ‏رَكْبًا ‏ ‏مَعَهُمْ ‏ ‏الْجُلْجُلُ ‏ ‏فَكَمْ ‏ ‏تَرَى فِي هَؤُلَاءِ مِنْ ‏ ‏جُلْجُلٍ ‏","","",""],[4581,4581,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ هُوَ النَّاجِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَضَعْتُمْ مَوْتَاكُمْ فِي الْقَبْرِ فَقُولُوا بِسْمِ اللَّهِ وَعَلَى ‏ ‏مِلَّةِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4582,4582,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْحَكَمِ الْبَجَلِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اتَّخَذَ كَلْبًا غَيْرَ كَلْبِ زَرْعٍ أَوْ ضَرْعٍ أَوْ صَيْدٍ نَقَصَ مِنْ عَمَلِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطٌ ‏ ‏فَقُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏إِنْ كَانَ فِي دَارٍ وَأَنَا لَهُ كَارِهٌ قَالَ هُوَ عَلَى رَبِّ الدَّارِ الَّذِي يَمْلِكُهَا ‏","","",""],[4583,4583,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ رُؤْيَا رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّاسَ قَدْ اجْتَمَعُوا فَقَامَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَنَزَعَ ‏ ‏ذَنُوبًا ‏ ‏أَوْ ‏ ‏ذَنُوبَيْنِ ‏ ‏وَفِي نَزْعِهِ ضَعْفٌ وَاللَّهُ يَغْفِرُ لَهُ ثُمَّ نَزَعَ ‏ ‏عُمَرُ ‏ ‏فَاسْتَحَالَتْ ‏ ‏غَرْبًا ‏ ‏فَمَا رَأَيْتُ عَبْقَرِيًّا مِنْ النَّاسِ ‏ ‏يَفْرِي ‏ ‏فَرِيَّهُ ‏ ‏حَتَّى ضَرَبَ النَّاسُ ‏ ‏بِعَطَنٍ ‏","","",""],[4584,4584,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الشَّهْرُ هَكَذَا وَهَكَذَا وَهَكَذَا وَقَبَضَ إِبْهَامَهُ فِي الثَّالِثَةِ ‏","","",""],[4585,4585,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ الْأَخْنَسِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَيْلُ فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[4586,4586,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْتَقَ ‏","","",""],[4587,4587,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَتَوَضَّأُ ثَلَاثًا يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَتَوَضَّأُ مَرَّةً يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4588,4588,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَاخَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏الَّتِي ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏فَصَلَّى بِهَا ‏","","",""],[4589,4589,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏سَمِعْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَكَادُ يَلْعَنُ ‏ ‏الْبَيْدَاءَ ‏ ‏وَيَقُولُ ‏ ‏إِنَّمَا ‏ ‏أَهَلَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْمَسْجِدِ ‏","","",""],[4590,4590,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏","","",""],[4591,4591,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏وَأَصْحَابُهُ مُلَبِّينَ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مُهِلِّينَ ‏ ‏بِالْحَجِّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ شَاءَ أَنْ يَجْعَلَهَا عُمْرَةً إِلَّا مَنْ كَانَ مَعَهُ ‏ ‏الْهَدْيُ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ أَيَرُوحُ أَحَدُنَا إِلَى ‏ ‏مِنًي ‏ ‏وَذَكَرُهُ يَقْطُرُ مَنِيًّا قَالَ نَعَمْ وَسَطَعَتْ ‏ ‏الْمَجَامِرُ ‏ ‏وَقَدِمَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏مِنْ ‏ ‏الْيَمَنِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَ ‏ ‏أَهْلَلْتَ ‏ ‏قَالَ ‏ ‏أَهْلَلْتُ ‏ ‏بِمَا ‏ ‏أَهَلَّ ‏ ‏بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏فَإِنَّ لَكَ مَعَنَا ‏ ‏هَدْيًا ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏فَحَدَّثْتُ بِهِ ‏ ‏طَاوُسًا ‏ ‏فَقَالَ هَكَذَا فَعَلَ الْقَوْمُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏اجْعَلْهَا عُمْرَةً ‏","","",""],[4592,4592,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا لَمْ يَشْرَبْهَا فِي الْآخِرَةِ إِلَّا أَنْ يَتُوبَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏","","",""],[4593,4593,"","","‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا ‏ ‏يَعْنِي ‏ ‏ضَنَّ ‏ ‏النَّاسُ بِالدِّينَارِ وَالدِّرْهَمِ وَتَبَايَعُوا بِالْعَيْنِ وَاتَّبَعُوا أَذْنَابَ الْبَقَرِ وَتَرَكُوا الْجِهَادَ فِي سَبِيلِ اللَّهِ أَنْزَلَ اللَّهُ بِهِمْ بَلَاءً فَلَمْ يَرْفَعْهُ عَنْهُمْ حَتَّى يُرَاجِعُوا دِينَهُمْ ‏","","",""],[4594,4594,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏فُضَيْلٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَمْسَى ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِصَلَاةِ الْعِشَاءِ حَتَّى صَلَّى الْمُصَلِّي وَاسْتَيْقَظَ الْمُسْتَيْقِظُ وَنَامَ النَّائِمُونَ ‏ ‏وَتَهَجَّدَ ‏ ‏الْمُتَهَجِّدُونَ ‏ ‏ثُمَّ خَرَجَ فَقَالَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي أَمَرْتُهُمْ أَنْ يُصَلُّوا هَذَا الْوَقْتَ ‏ ‏أَوْ هَذِهِ الصَّلَاةَ أَوْ نَحْوَ ذَا ‏","","",""],[4595,4595,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏أَنَّ ‏ ‏الْعَبَّاسَ ‏ ‏اسْتَأْذَنَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَنْ يَبِيتَ تِلْكَ اللَّيْلَةَ ‏ ‏بِمَكَّةَ ‏ ‏مِنْ أَجْلِ ‏ ‏السِّقَايَةِ ‏ ‏فَأَذِنَ لَهُ ‏","","",""],[4596,4596,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يَهْجَعُ ‏ ‏هَجْعَةً ‏ ‏بِالْبَطْحَاءِ ‏ ‏وَذَكَرَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ ذَلِكَ ‏","","",""],[4597,4597,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏فَرْقَدٍ السَّبَخِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ادَّهَنَ بِزَيْتٍ غَيْرِ ‏ ‏مُقَتَّتٍ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[4598,4598,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ مُسْكِرٍ خَمْرٌ وَكُلُّ خَمْرٍ حَرَامٌ ‏","","",""],[4599,4599,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مُسْكِرٍ خَمْرٌ وَكُلُّ مُسْكِرٍ حَرَامٌ ‏","","",""],[4600,4600,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ مُحَمَّدٍ ‏ ‏سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ هَذَا الْأَمْرُ فِي ‏ ‏قُرَيْشٍ ‏ ‏مَا بَقِيَ مِنْ النَّاسِ اثْنَانِ قَالَ وَحَرَّكَ إِصْبَعَيْهِ ‏ ‏يَلْوِيهِمَا هَكَذَا ‏","","",""]];
